+pattern_accepts() {
+    local p
+    for p in "${VALID_MODEL_PATTERNS[@]}"; do
+        [[ "$1" =~ $p ]] && return 0
+    done
+    return 1
+}
+
+@test "VALID_MODEL_PATTERNS admit the 5-family dash forms (claude-opus-5, claude-sonnet-5, claude-fable-5-1, claude-opus-5-5, claude-fable-6)" {
